# Kind mapping per language family
def kind_map(lang):
    m={
     'root':'program','call':'call_expression','arguments':'arguments','member':'member_expression','binary':'binary_expression','unary':'unary_expression','assignment':'assignment_expression','block':'statement_block','function':'function_declaration','function_expr':'function_expression','class':'class_declaration','if':'if_statement','for':'for_statement','while':'while_statement','return':'return_statement','import':'import_statement','vardecl':'lexical_declaration','subscript':'subscript_expression','object':'object','array':'array','paren':'parenthesized_expression','parameters':'formal_parameters','declarator':'variable_declarator'
    }
    if lang=='Python':
        m.update({'root':'module','call':'call','arguments':'argument_list','member':'attribute','binary':'binary_operator','unary':'unary_operator','assignment':'assignment','block':'block','function':'function_definition','function_expr':'function_definition','class':'class_definition','parameters':'parameters','vardecl':'assignment','declarator':'assignment'})
    elif lang=='Ruby':
        m.update({'root':'program','call':'call','arguments':'argument_list','member':'call','binary':'binary','assignment':'assignment','block':'body_statement','function':'method','function_expr':'method','class':'class','parameters':'method_parameters'})
    elif lang=='Go':
        m.update({'root':'source_file','arguments':'argument_list','member':'selector_expression','block':'block','parameters':'parameter_list'})
    elif lang=='Rust':
        m.update({'root':'source_file','arguments':'arguments','member':'field_expression','block':'block','function':'function_item','function_expr':'function_item','parameters':'parameters'})
    elif lang=='Java':
        m.update({'root':'program','call':'method_invocation','arguments':'argument_list','block':'block','function':'method_declaration','function_expr':'method_declaration','parameters':'formal_parameters'})
    elif lang in ('C','Cpp'):
        m.update({'root':'translation_unit','arguments':'argument_list','member':'field_expression','block':'compound_statement','function':'function_definition','function_expr':'function_definition','parameters':'parameter_list'})
    elif lang=='CSharp':
        m.update({'root':'compilation_unit','call':'invocation_expression','arguments':'argument_list','member':'member_access_expression','block':'block','function':'method_declaration','function_expr':'method_declaration'})
    elif lang=='Php':
        m.update({'root':'program','call':'function_call_expression','arguments':'arguments','member':'member_access_expression','block':'compound_statement','function':'function_definition','function_expr':'anonymous_function'})
    elif lang in ('Kotlin','Scala','Swift','Dart'):
        m.update({'root':'source_file','block':'block','function':'function_declaration','function_expr':'function_declaration'})
        if lang=='Dart': m['root']='source_file'
    elif lang=='Lua':
        m.update({'root':'chunk','call':'function_call','arguments':'arguments','function':'function_declaration','block':'block'})
    elif lang=='Elixir':
        m.update({'root':'source','call':'call','arguments':'arguments','binary':'binary_operator','block':'block'})
    elif lang=='Bash':
        m.update({'root':'program','call':'command','arguments':'command','member':'binary_expression','function':'function_definition','block':'compound_statement'})
    elif lang=='Haskell':
        m.update({'root':'module','call':'function','binary':'binary_operator','function':'function'})
    elif lang=='Html':
        m.update({'root':'document'})
    elif lang=='Css':
        m.update({'root':'stylesheet','call':'call_expression'})
    elif lang=='Json':
        m.update({'root':'document'})
    elif lang=='Yaml':
        m.update({'root':'stream'})
    return m

