class Parser:
    def __init__(self,src,lang):
        self.src=src; self.lang=lang or 'JavaScript'; self.km=kind_map(self.lang)
        toks,comments=tokenize(src,self.lang)
        self.toks=toks; self.comments=comments; self.pos=0; self.has_error=False
        # python lines indent map: token line
        self.lines=src.split('\n')
    def peek(self,off=0):
        idx=self.pos+off
        if idx < len(self.toks): return self.toks[idx]
        return Tok('','eof',len(self.src),len(self.src))
    def at(self,text):
        return self.peek().text==text
    def at_eof(self): return self.pos>=len(self.toks)
    def advance(self):
        t=self.peek()
        if self.pos < len(self.toks): self.pos+=1
        return t
    def expect(self,text):
        if self.at(text): return self.advance()
        self.has_error=True
        # return synthetic
        p=self.peek()
        return Tok(text,'punct',p.start,p.start)
    def line_of(self,pos_char):
        # returns line number 0-based
        return self.src.count('\n',0,pos_char)
    def col_of(self,tok): pass
    def node(self,kind,start,end,children,fields=None,named=True):
        if fields is None: fields=[None]*len(children)
        nd=Node(kind,start,end,children,fields,named,self.src)
        return nd
    def tnode(self,tok): return tok_node(tok,self.src)
    # ---------- entry ----------
    def parse_program(self):
        if self.lang=='Python':
            children=self.parse_py_statements(0)
            end=self.toks[-1].end if self.toks else 0
            # program range: tree-sitter python module range is whole file? Usually 0..len
            root=self.node(self.km['root'],0,len(self.src),children)
        else:
            children=[]
            while not self.at_eof():
                if self.at('}'): self.has_error=True; self.advance(); continue
                stmt=self.parse_statement()
                if stmt is not None: children.append(stmt)
            end=len(self.src)
            root=self.node(self.km['root'],0,end,children)
        self.insert_comments(root)
        return root
    def insert_comments(self,root):
        if not self.comments: return
        comment_nodes=[Node('comment',t.start,t.end,[],[],True,self.src) for t in self.comments]
        for cn in comment_nodes:
            # find deepest node containing it, not itself,
            target=root
            changed=True
            while changed:
                changed=False
                for c in target.children:
                    if c.named and c.start<=cn.start and cn.end<=c.end and c is not cn and (c.end-c.start)<(target.end-target.start) or (c is not cn and c.start<=cn.start and cn.end<=c.end and c.kind not in ('string',)):
                        # choose first containing child
                        if c.start<=cn.start and cn.end<=c.end:
                            target=c; changed=True; break
                # loop safety: if target child == target break
            # avoid inserting into leaf string etc or leaf with no children and kind != root/block types? If deepest is leaf identifier etc containing comment impossible bc range
            # Insert sorted
            idx=0
            while idx < len(target.children) and target.children[idx].start < cn.start: idx+=1
            target.children.insert(idx,cn); target.fields.insert(idx,None); cn.parent=target
    # ---------- C-like statements ----------
    def parse_block(self):
        ltok=self.expect('{')
        children=[self.tnode(ltok)]
        fields=[None]
        while not self.at_eof() and not self.at('}'):
            stmt=self.parse_statement()
            if stmt is not None: children.append(stmt); fields.append(None)
        if self.at('}'):
            rt=self.advance(); children.append(self.tnode(rt)); fields.append(None)
        else: self.has_error=True; rt=ltok
        kind=self.km['block']
        return self.node(kind,ltok.start,children[-1].end,children,fields)
    def parse_statement(self):
        if self.at_eof(): return None
        t=self.peek(); txt=t.text
        try:
            if txt=='{': return self.parse_block()
            if txt==';':
                tok=self.advance(); return self.node('empty_statement',tok.start,tok.end,[self.tnode(tok)])
            if txt=='@':
                # decorator
                start=self.advance(); expr=self.parse_expression()
                dec=self.node('decorator',start.start,expr.end,[self.tnode(start),expr])
                nxt=self.parse_statement()
                if nxt: return self.node(nxt.kind,nxt.start,nxt.end,[dec]+nxt.children,[None]+nxt.fields) if False else nxt
                return dec
            if txt in ('if',): return self.parse_if()
            if txt in ('while',): return self.parse_while()
            if txt=='do': return self.parse_do()
            if txt=='for': return self.parse_for()
            if txt=='switch': return self.parse_switch()
            if txt=='try': return self.parse_try()
            if txt in ('return','throw','yield','break','continue','goto'):
                tok=self.advance(); children=[self.tnode(tok)]; end=tok.end
                # optional arg if not ; } EOF
                if not self.at_eof() and not self.at(';') and not self.at('}'):
                    # for break/continue only identifier
                    expr=self.parse_expression()
                    children.append(expr)
                if self.at(';'):
                    semi=self.advance(); children.append(self.tnode(semi))
                kindmap={'return':'return_statement','throw':'throw_statement','break':'break_statement','continue':'continue_statement','yield':'yield_expression','goto':'goto_statement'}
                return self.node(kindmap.get(txt,'return_statement'),tok.start,children[-1].end,children)
            if txt=='function' or (txt=='async' and self.peek(1).text=='function') or (txt=='export' and self.peek(1).text=='function'):
                return self.parse_function_decl()
            if txt=='class' or (txt in ('abstract',) and self.peek(1).text=='class'):
                return self.parse_class_decl()
            if txt in ('let','var','const'):
                return self.parse_var_decl()
            if txt=='import': return self.parse_import()
            if txt=='export': return self.parse_export()
            if txt in ('type','interface','enum','namespace','declare'):
                return self.parse_type_decl()
            if txt=='package':
                tok=self.advance(); children=[self.tnode(tok)]
                while not self.at_eof() and not self.at(';') and not self.at('{'):
                    children.append(self.parse_primary_or_token())
                if self.at(';'): children.append(self.tnode(self.advance()))
                return self.node('package_clause' if self.lang=='Go' else 'package_declaration',tok.start,children[-1].end,children)
            if txt in ('public','private','protected','static','final','abstract','async','sealed','override','open','inline','suspend'):
                # modifier-led member/decl: try if next tokens form function/class, else fallthrough expression
                save=self.pos
                # peek ahead: if there's identifier + '(' within few tokens or class/function keyword, treat as function decl generic
                ahead=[self.peek(i).text for i in range(6)]
                if 'class' in ahead or 'function' in ahead or 'fun' in ahead:
                    return self.parse_function_or_class_with_modifiers()
                # Java-like method: modifier type name (...)
                if self.lang in ('Java','CSharp','Cpp','C','Kotlin','Scala','Swift','Dart','Php'):
                    return self.parse_generic_decl_or_expr()
            if txt in ('fun','fn','func','def'):
                return self.parse_named_function(txt)
            if txt in ('struct','trait','impl','module','object','extension'):
                return self.parse_generic_type_container(txt)
        except Exception as e:
            self.has_error=True
            # ensure progress
            if self.pos < len(self.toks): self.advance()
            return self.node('expression_statement',t.start,t.end,[])
        # expression statement
        expr=self.parse_expression()
        children=[expr]; end=expr.end
        if self.at(';'):
            semi=self.advance(); children.append(self.tnode(semi)); end=semi.end
        return self.node('expression_statement',expr.start,end,children)
    def parse_primary_or_token(self):
        t=self.peek()
        if t.type in ('ident','number','string'):
            return self.parse_primary()
        tok=self.advance(); return self.tnode(tok)
    def parse_if(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.at('('):
            cond=self.parse_paren_expr(); children.append(cond)
        else:
            children.append(self.parse_expression())
        # then keyword for some languages
        if self.at('then'): children.append(self.tnode(self.advance()))
        cons=self.parse_statement() if not self.at_eof() else None
        if cons: children.append(cons)
        end=children[-1].end
        if self.at('else'):
            etok=self.advance(); echildren=[self.tnode(etok)]
            if self.at('if'):
                nested=self.parse_if(); echildren.append(nested)
            else:
                st=self.parse_statement(); 
                if st: echildren.append(st)
            els=self.node('else_clause',etok.start,echildren[-1].end,echildren)
            children.append(els)
        elif self.at('elif'):
            nested=self.parse_if(); children.append(nested)
        return self.node(self.km['if'],tok.start,children[-1].end,children,[None, 'condition' if len(children)>1 else None]+[None]*(len(children)-2))
    def parse_while(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.at('('): children.append(self.parse_paren_expr())
        else: children.append(self.parse_expression())
        if self.at('do'): children.append(self.tnode(self.advance()))
        body=self.parse_statement() if not self.at_eof() else None
        if body: children.append(body)
        return self.node(self.km['while'],tok.start,children[-1].end,children)
    def parse_do(self):
        tok=self.advance(); children=[self.tnode(tok)]
        body=self.parse_statement(); 
        if body: children.append(body)
        if self.at('while'):
            w=self.advance(); children.append(self.tnode(w))
            if self.at('('): children.append(self.parse_paren_expr())
        if self.at(';'): children.append(self.tnode(self.advance()))
        return self.node('do_statement',tok.start,children[-1].end,children)
    def parse_for(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.at('('):
            lt=self.advance(); children.append(self.tnode(lt))
            # header: parse segments separated by ; or , handling var decl
            while not self.at_eof() and not self.at(')'):
                if self.at(';') or self.at(','):
                    children.append(self.tnode(self.advance())); continue
                if self.peek().text in ('let','var','const'):
                    children.append(self.parse_var_decl(in_for=True))
                else:
                    children.append(self.parse_expression())
            if self.at(')'): children.append(self.tnode(self.advance()))
        else:
            children.append(self.parse_expression())
        body=self.parse_statement() if not self.at_eof() else None
        if body: children.append(body)
        # Determine for_in if header contains in/of as tokens/text in children?
        txt=self.src[tok.start:children[-1].end] if children else ''
        kind=self.km['for']
        # JS kinds: for_in_statement if ' in ' or ' of ' inside parens
        if self.lang in ('JavaScript','TypeScript','Tsx'):
            # check tokens in header
            hdr=[c.text for c in children]
            # simpler scan token texts between parentheses
            pass
        return self.node(kind,tok.start,children[-1].end,children)
    def parse_switch(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.at('('): children.append(self.parse_paren_expr())
        else: children.append(self.parse_expression())
        if self.at('{'):
            body=self.parse_switch_body(); children.append(body)
        return self.node('switch_statement',tok.start,children[-1].end,children)
    def parse_switch_body(self):
        lt=self.expect('{'); children=[self.tnode(lt)]
        while not self.at_eof() and not self.at('}'):
            if self.at('case') or self.at('default'):
                ctok=self.advance(); cchildren=[self.tnode(ctok)]
                if ctok.text=='case': cchildren.append(self.parse_expression())
                if self.at(':') or self.at('{'):
                    # colon token or use?
                    if self.at(':'): cchildren.append(self.tnode(self.advance()))
                # statements until next case/default/}
                while not self.at_eof() and not self.at('}') and not self.at('case') and not self.at('default'):
                    st=self.parse_statement(); 
                    if st: cchildren.append(st)
                kind='switch_case' if ctok.text=='case' else 'switch_default'
                children.append(self.node(kind,ctok.start,cchildren[-1].end,cchildren))
            else:
                st=self.parse_statement()
                if st: children.append(st)
        if self.at('}'): children.append(self.tnode(self.advance()))
        return self.node('switch_body',lt.start,children[-1].end,children)
    def parse_try(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.at('{'): children.append(self.parse_block())
        else:
            st=self.parse_statement(); 
            if st: children.append(st)
        while self.at('catch') or self.at('except'):
            ctok=self.advance(); cchildren=[self.tnode(ctok)]
            if self.at('('): cchildren.append(self.parse_paren_params_or_expr())
            if self.at('{'): cchildren.append(self.parse_block())
            children.append(self.node('catch_clause',ctok.start,cchildren[-1].end,cchildren))
        if self.at('finally'):
            ftok=self.advance(); fchildren=[self.tnode(ftok)]
            if self.at('{'): fchildren.append(self.parse_block())
            children.append(self.node('finally_clause',ftok.start,fchildren[-1].end,fchildren))
        return self.node('try_statement',tok.start,children[-1].end,children)
    def parse_paren_expr(self):
        lt=self.expect('('); children=[self.tnode(lt)]
        if not self.at(')'):
            children.append(self.parse_expression())
            while self.at(','):
                children.append(self.tnode(self.advance())); children.append(self.parse_expression())
        rt=self.expect(')'); children.append(self.tnode(rt))
        kind=self.km['paren']
        return self.node(kind,lt.start,rt.end,children)
    def parse_paren_params_or_expr(self):
        # for catch
        return self.parse_paren_expr()
    def parse_function_decl(self):
        return self.parse_function(is_decl=True)
    def parse_function(self,is_decl=True,skip_kw=False):
        start_tok=self.peek(); children=[]
        start=start_tok.start
        if self.at('async') or self.at('export') or self.at('default'):
            children.append(self.tnode(self.advance()))
        if self.at('function'):
            ft=self.advance(); children.append(self.tnode(ft))
        elif not skip_kw:
            # named keyword handled elsewhere
            pass
        gen=False
        if self.at('*'): children.append(self.tnode(self.advance())); gen=True
        name=None
        if self.peek().type=='ident' and not self.at('('):
            nt=self.advance(); name=leaf_node('identifier',nt,self.src); children.append(name)
        params=self.parse_params()
        children.append(params)
        # return type annotation
        if self.at(':'):
            ann=self.parse_type_annotation(); children.append(ann)
        if self.at('{'):
            body=self.parse_block(); children.append(body)
        elif self.at(';'):
            children.append(self.tnode(self.advance()))
        elif self.at('=>'):
            children.append(self.tnode(self.advance())); children.append(self.parse_expression())
        kind=self.km['function'] if is_decl else self.km['function_expr']
        if gen and self.lang in ('JavaScript','TypeScript','Tsx'): kind='generator_function_declaration' if is_decl else 'generator_function'
        return self.node(kind,start,children[-1].end if children else start,children)
    def parse_named_function(self,kw):
        # func/fn/fun/def for non-python languages
        start=self.peek(); children=[self.tnode(self.advance())]
        # generics etc skip <...>
        if self.at('<'):
            children.append(self.parse_type_args_node())
        name=None
        if self.peek().type=='ident' and not self.at('('):
            nt=self.advance(); name=leaf_node('identifier',nt,self.src); children.append(name)
        if self.at('('): children.append(self.parse_params())
        if self.at(':'):
            # return type until { or = or newline block
            try: children.append(self.parse_type_annotation())
            except: pass
        if self.at('='):
            children.append(self.tnode(self.advance())); 
            if self.at('{'): children.append(self.parse_block())
            else: children.append(self.parse_expression())
        elif self.at('{'): children.append(self.parse_block())
        kind=self.km['function']
        return self.node(kind,start.start,children[-1].end,children)
    def parse_function_or_class_with_modifiers(self):
        start=self.peek(); mods=[]
        while self.peek().text in ('public','private','protected','static','final','abstract','async','sealed','override','open','default','export'):
            mods.append(self.tnode(self.advance()))
        if self.at('class'): node=self.parse_class_decl()
        elif self.at('function') or self.at('fun') or self.at('fn'): 
            # dispatch
            if self.at('function'): node=self.parse_function(is_decl=True)
            else: node=self.parse_named_function(self.peek().text)
        else: node=self.parse_generic_decl_or_expr()
        if mods:
            return self.node(node.kind,mods[0].start,node.end,mods+node.children)
        return node
    def parse_generic_decl_or_expr(self):
        # Java-like: modifiers? type name ( params ) block etc. Fallback parse expression statement but transform call?
        start_pos=self.pos; start_tok=self.peek()
        # Collect tokens until '(' '{' ';' '=' etc scanning.
        # Try pattern: [modifiers] [type identifiers/generics] name '('
        expr=self.parse_expression()
        # if expr is call and preceded by type tokens consumed as... expression parser may have parsed name as call callee only.
        children=[expr]
        if self.at('{'):
            body=self.parse_block(); children.append(body)
            # Build method declaration node spanning
            return self.node(self.km['function'],start_tok.start,body.end,children)
        if self.at(';'): children.append(self.tnode(self.advance()))
        return self.node('expression_statement',start_tok.start,children[-1].end,children)
    def parse_generic_type_container(self,kw):
        start=self.advance(); children=[self.tnode(start)]
        if self.peek().type=='ident': children.append(leaf_node('identifier',self.advance(),self.src))
        while not self.at_eof() and not self.at('{') and not self.at(';'):
            children.append(self.parse_primary_or_token())
            if len(children)>20: break
        if self.at('{'): children.append(self.parse_class_body() if kw in ('struct','trait') else self.parse_block())
        kind={'struct':'struct_item','trait':'trait_item','impl':'impl_item','module':'module','object':'object_definition','extension':'extension'}.get(kw,'declaration')
        if self.lang=='Rust': kind={'struct':'struct_item','trait':'trait_item','impl':'impl_item','module':'mod_item'}.get(kw,kind)
        return self.node(kind,start.start,children[-1].end,children)
    def parse_params(self):
        lt=self.expect('('); children=[self.tnode(lt)]; fields=[None]
        while not self.at_eof() and not self.at(')'):
            if self.at(','):
                children.append(self.tnode(self.advance())); fields.append(None); continue
            if self.at('...') or self.at('*'):
                rt=self.advance(); 
                inner=self.parse_param_atom()
                rn=self.node('rest_pattern' if self.lang in ('JavaScript','TypeScript','Tsx') else 'variadic_parameter',rt.start,inner.end,[self.tnode(rt),inner])
                children.append(rn); fields.append(None); continue
            param=self.parse_param_atom()
            children.append(param); fields.append(None)
            if self.at(':'):
                ann=self.parse_type_annotation(); 
                # attach annotation as sibling? Original formal_parameters children include param (?) In TS parameter node is required_parameter containing identifier + annotation.
                # Wrap param+ann into a node if param is identifier?
                prev=children.pop(); fields.pop()
                wrapped=self.node('required_parameter',prev.start,ann.end,[prev,ann])
                children.append(wrapped); fields.append(None)
            if self.at('='):
                eq=self.advance(); val=self.parse_expression()
                prev=children[-1]
                # assignment_pattern for JS
                kind_p='assignment_pattern' if self.lang in ('JavaScript','TypeScript','Tsx') else prev.kind
                if prev.kind in ('identifier','array_pattern','object_pattern','required_parameter'):
                    children[-1]=self.node(kind_p,prev.start,val.end,[prev,self.tnode(eq),val])
                else:
                    children.append(self.tnode(eq)); children.append(val); fields.extend([None,None])
            # ensure progress
        rt=self.expect(')'); children.append(self.tnode(rt)); fields.append(None)
        return self.node(self.km['parameters'],lt.start,rt.end,children,fields)
    def parse_param_atom(self):
        t=self.peek()
        if t.text=='{':
            obj=self.parse_object(); obj.kind='object_pattern'; return obj
        if t.text=='[':
            arr=self.parse_array(); arr.kind='array_pattern'; return arr
        if t.text=='(':
            return self.parse_params()
        if t.type=='ident':
            nt=self.advance(); 
            # type-like identifier? keep identifier
            return leaf_node('identifier',nt,self.src)
        return self.parse_expression()
    def parse_type_annotation(self):
        ct=self.expect(':'); children=[self.tnode(ct)]
        typ=self.parse_type()
        if typ: children.append(typ)
        return self.node('type_annotation',ct.start,children[-1].end,children)
    def parse_type(self):
        # parse type atoms with suffixes and unions
        left=self.parse_type_atom()
        if left is None: return None
        while self.peek().text in ('|','&'):
            op=self.advance(); right=self.parse_type_atom()
            if right is None: break
            kind='union_type' if op.text=='|' else 'intersection_type'
            left=self.node(kind,left.start,right.end,[left,self.tnode(op),right])
        return left
    def parse_type_atom(self):
        t=self.peek()
        if t.text=='{':
            # object type: consume balanced
            lt=self.advance(); children=[self.tnode(lt)]
            while not self.at_eof() and not self.at('}'):
                if self.at(',') or self.at(';'): children.append(self.tnode(self.advance())); continue
                # property signature: name ?/: type
                if self.peek().type=='ident':
                    nt=self.advance(); prop=leaf_node('property_identifier',nt,self.src)
                    pchildren=[prop]
                    if self.at('?'): pchildren.append(self.tnode(self.advance()))
                    if self.at(':'): pchildren.append(self.parse_type_annotation())
                    children.append(self.node('property_signature',nt.start,pchildren[-1].end,pchildren))
                else:
                    children.append(self.parse_primary_or_token())
            rt=self.expect('}'); children.append(self.tnode(rt))
            return self.node('object_type',lt.start,rt.end,children)
        if t.text=='(':
            lt=self.advance(); children=[self.tnode(lt)]
            inner=self.parse_type()
            if inner: children.append(inner)
            while self.at(','): children.append(self.tnode(self.advance())); children.append(self.parse_type())
            rt=self.expect(')'); children.append(self.tnode(rt))
            return self.node('parenthesized_type',lt.start,rt.end,children)
        if t.text=='[':
            arr=self.parse_array(); return arr
        if t.type=='ident' or t.text in ('string','number','boolean','any','void','unknown','object','symbol','bigint','never','undefined'):
            nt=self.advance()
            kind='type_identifier' if nt.text and nt.text[0].isupper() or self.lang in ('TypeScript','Tsx','Java','Go','Rust','CSharp','Kotlin','Scala','Swift') else 'predefined_type'
            if nt.text in ('string','number','boolean','any','void','unknown','object','symbol','bigint','never','undefined','int','float','bool','char','double','long','short','byte'): kind='predefined_type'
            node=leaf_node(kind,nt,self.src)
            # generics
            if self.at('<'):
                args=self.parse_type_args_node(); node=self.node('generic_type',nt.start,args.end,[node,args])
            while self.at('['):
                lt=self.advance(); rt=self.expect(']'); node=self.node('array_type',node.start,rt.end,[node,self.tnode(lt),self.tnode(rt)])
            if self.at('?'): 
                qt=self.advance(); node=self.node('optional_type',node.start,qt.end,[node,self.tnode(qt)])
            return node
        if t.type=='string':
            st=self.advance(); return leaf_node('literal_type',st,self.src)
        # fallback consume
        if not self.at_eof():
            tok=self.advance(); return self.tnode(tok)
        return None
    def parse_type_args_node(self):
        lt=self.expect('<'); children=[self.tnode(lt)]
        while not self.at_eof() and not self.at('>'):
            if self.at(','): children.append(self.tnode(self.advance())); continue
            typ=self.parse_type(); 
            if typ: children.append(typ)
            else: break
        rt=self.expect('>'); children.append(self.tnode(rt))
        return self.node('type_arguments',lt.start,rt.end,children)
    def parse_class_decl(self):
        start_tok=self.peek(); children=[]
        if self.at('abstract'): children.append(self.tnode(self.advance()))
        ct=self.advance(); children.append(self.tnode(ct)) # class
        if self.peek().type=='ident' and not self.at('{') and not self.at('<'):
            nt=self.advance(); children.append(leaf_node('identifier',nt,self.src))
        if self.at('<'): children.append(self.parse_type_args_node())
        # heritage
        while self.peek().text in ('extends','implements',':'):
            kw=self.advance(); hchildren=[self.tnode(kw)]
            typ=self.parse_type() if kw.text==':' else self.parse_expression()
            if typ: hchildren.append(typ)
            while self.at(','):
                hchildren.append(self.tnode(self.advance())); hchildren.append(self.parse_expression())
            kindc='class_heritage' if self.lang in ('JavaScript','TypeScript','Tsx') else 'object_type'  # placeholder
            children.append(self.node(kindc,kw.start,hchildren[-1].end,hchildren))
            if kw.text==':' and self.at('{'): break
        if self.at('{'):
            body=self.parse_class_body(); children.append(body)
        kind=self.km['class']
        return self.node(kind,start_tok.start,children[-1].end if children else ct.end,children)
    def parse_class_body(self):
        lt=self.expect('{'); children=[self.tnode(lt)]
        while not self.at_eof() and not self.at('}'):
            if self.at(';'):
                children.append(self.tnode(self.advance())); continue
            member=self.parse_class_member()
            if member: children.append(member)
        rt=self.expect('}'); children.append(self.tnode(rt))
        kind='class_body' if self.lang in ('JavaScript','TypeScript','Tsx','Python') else self.km['block']
        if self.lang=='Python': kind='block'
        return self.node(kind,lt.start,rt.end,children)
    def parse_class_member(self):
        start=self.peek(); children=[]
        # modifiers
        while self.peek().text in ('public','private','protected','static','async','readonly','abstract','final','override','get','set','declare','accessor','sealed','virtual','override','internal','protected','open','data'):
            # stop if modifier is actually name of method? If next next token is '(' and current is get/set keep as name? handle below if only token
            if self.peek().text in ('get','set') and self.peek(2).text=='(':
                break
            children.append(self.tnode(self.advance()))
            if children[-1].text=='static' and self.at('{'):
                blk=self.parse_block(); children.append(blk)
                return self.node('class_static_block',start.start,blk.end,children)
        # constructor etc name
        if self.at('#'):
            ht=self.advance(); children.append(self.tnode(ht))
        if self.peek().type=='ident' or self.peek().type=='string' or self.peek().type=='number':
            nt=self.advance(); name_kind='property_identifier'
            if self.lang=='Python': name_kind='identifier'
            name=leaf_node(name_kind,nt,self.src); children.append(name)
        elif self.at('['):
            # computed
            lt=self.advance(); expr=self.parse_expression(); rt=self.expect(']')
            comp=self.node('computed_property_name',lt.start,rt.end,[self.tnode(lt),expr,self.tnode(rt)])
            children.append(comp)
        elif self.at('*'):
            children.append(self.tnode(self.advance()))
            if self.peek().type=='ident':
                nt=self.advance(); children.append(leaf_node('property_identifier',nt,self.src))
            else:
                self.has_error=True; return self.node('method_definition',start.start,start.end,children)
        else:
            tok=self.advance(); children.append(self.tnode(tok)); return self.node('field_definition',start.start,tok.end,children)
        # type annotation
        if self.at('?'): children.append(self.tnode(self.advance()))
        if self.at(':'):
            children.append(self.parse_type_annotation())
        if self.at('('):
            params=self.parse_params(); children.append(params)
