            # If expr came from identifier after async, we need node for async identifier as left
            # Simple: create sequence? fallback return expr
            return expr
        return self.parse_postfix(self.parse_primary())
    def parse_postfix(self,left):
        while True:
            t=self.peek()
            if t.text in ('.','?.'):
                # member
                op=self.advance()
                if self.peek().type=='ident' or self.peek().text in KEYWORDS or self.peek().type=='number':
                    nt=self.advance(); prop_kind='property_identifier' if self.lang in ('JavaScript','TypeScript','Tsx') else 'identifier'
                    if self.lang in ('Go',): prop_kind='field_identifier'
                    if self.lang in ('Rust','Java','C','Cpp'): prop_kind='field_identifier'
                    prop=leaf_node(prop_kind,nt,self.src)
                else:
                    self.has_error=True; prop=self.tnode(self.advance()) if not self.at_eof() else self.tnode(op)
                kind=self.km['member']
                if self.lang=='Python': kind='attribute'
                left=self.node(kind,left.start,prop.end,[left,self.tnode(op),prop],['object' if self.lang!='Python' else 'attribute',None,'property' if self.lang!='Python' else 'attribute'])
                continue
            if t.text=='::':
                op=self.advance()
                if self.peek().type=='ident': nt=self.advance(); prop=leaf_node('identifier',nt,self.src)
                else: prop=self.tnode(self.advance())
                left=self.node('scoped_identifier' if self.lang=='Rust' else self.km['member'],left.start,prop.end,[left,self.tnode(op),prop])
                continue
            if t.text in ('->','->*'):
                op=self.advance()
                if self.peek().type=='ident': nt=self.advance(); prop=leaf_node('field_identifier',nt,self.src)
                else: prop=self.tnode(self.advance())
                left=self.node(self.km['member'],left.start,prop.end,[left,self.tnode(op),prop])
                continue
            if t.text=='(':
                args=self.parse_arguments()
                kind=self.km['call']
                left=self.node(kind,left.start,args.end,[left,args],['function','arguments'])
                continue
            if t.text=='[':
                lt=self.advance(); children=[left,self.tnode(lt)]
                if not self.at(']'):
                    children.append(self.parse_expression())
                    while self.at(','):
                        children.append(self.tnode(self.advance())); 
                        if not self.at(']'): children.append(self.parse_expression())
                rt=self.expect(']'); children.append(self.tnode(rt))
                left=self.node(self.km['subscript'],left.start,rt.end,children)
                continue
            if t.text in ('++','--'):
                op=self.advance(); left=self.node('update_expression',left.start,op.end,[left,self.tnode(op)]); continue
            if t.text=='!' and self.lang in ('TypeScript','Tsx'):
                op=self.advance(); left=self.node('non_null_expression',left.start,op.end,[left,self.tnode(op)]); continue
            if t.type=='string' and left.kind not in ('string',):
                # tagged template
                st=self.advance(); tpl=leaf_node('template_string',st,self.src)
                left=self.node('tagged_template_expression',left.start,st.end,[left,tpl]); continue
            if t.text=='<' and self.lang in ('Tsx','TypeScript','Rust','Go'):
                # possible generic call - ambiguous, do not consume (let binary handle as comparison)
                break
            break
        return left
    def parse_arguments(self):
        lt=self.expect('('); children=[self.tnode(lt)]; fields=[None]
        while not self.at_eof() and not self.at(')'):
            if self.at(','):
                children.append(self.tnode(self.advance())); fields.append(None); continue
            if self.at('...'):
                rt=self.advance(); inner=self.parse_assign_expr()
                children.append(self.node('spread_element',rt.start,inner.end,[self.tnode(rt),inner])); fields.append(None); continue
            if self.lang=='Python' and self.peek().type=='ident' and self.peek(1).text=='=':
                nt=self.advance(); eq=self.advance(); val=self.parse_assign_expr()
                children.append(self.node('keyword_argument',nt.start,val.end,[leaf_node('identifier',nt,self.src),self.tnode(eq),val])); fields.append(None); continue
            if self.at('*') or self.at('**'):
                # python starred
                rt=self.advance(); inner=self.parse_assign_expr()
                children.append(inner); fields.append(None); continue
            arg=self.parse_assign_expr()
            children.append(arg); fields.append(None)
            # sequences via comma tokens handled loop
        rt=self.expect(')'); children.append(self.tnode(rt)); fields.append(None)
        return self.node(self.km['arguments'],lt.start,rt.end,children,fields)
    def parse_array(self):
        lt=self.expect('['); children=[self.tnode(lt)]
        while not self.at_eof() and not self.at(']'):
            if self.at(','): children.append(self.tnode(self.advance())); continue
            if self.at('...'):
                rt=self.advance(); inner=self.parse_assign_expr(); children.append(self.node('spread_element',rt.start,inner.end,[self.tnode(rt),inner])); continue
            children.append(self.parse_assign_expr())
        rt=self.expect(']'); children.append(self.tnode(rt))
        kind=self.km['array']
        if self.lang=='Python': kind='list'
        return self.node(kind,lt.start,rt.end,children)
    def parse_object(self):
        lt=self.expect('{'); children=[self.tnode(lt)]
        while not self.at_eof() and not self.at('}'):
            if self.at(','): children.append(self.tnode(self.advance())); continue
            if self.at(';'): children.append(self.tnode(self.advance())); continue
            if self.at('...'):
                rt=self.advance(); inner=self.parse_assign_expr(); children.append(self.node('spread_element',rt.start,inner.end,[self.tnode(rt),inner])); continue
            entry=self.parse_object_entry(); 
            if entry: children.append(entry)
        rt=self.expect('}'); children.append(self.tnode(rt))
        kind=self.km['object']
        if self.lang=='Python': kind='dictionary'
        return self.node(kind,lt.start,rt.end,children)
    def parse_object_entry(self):
        start=self.peek()
        # method: name '('
        if (start.type in ('ident','string','number')) and self.peek(1).text=='(':
            nt=self.advance(); name=leaf_node('property_identifier',nt,self.src) if start.type=='ident' else leaf_node('string' if start.type=='string' else 'number',nt,self.src)
            params=self.parse_params(); children=[name,params]
            if self.at('{'): children.append(self.parse_block())
            return self.node('method_definition',start.start,children[-1].end,children)
        if start.text=='[':
            lt=self.advance(); expr=self.parse_expression(); rt=self.expect(']')
            comp=self.node('computed_property_name',lt.start,rt.end,[self.tnode(lt),expr,self.tnode(rt)])
            if self.at(':'):
                ct=self.advance(); val=self.parse_assign_expr()
                return self.node('pair',start.start,val.end,[comp,self.tnode(ct),val])
            return comp
        if start.type=='ident' and self.peek(1).text in (':','='):
            nt=self.advance(); name=leaf_node('property_identifier',nt,self.src)
            sep=self.advance(); val=self.parse_assign_expr()
            return self.node('pair',start.start,val.end,[name,self.tnode(sep),val],['key',None,'value'] if self.lang=='Python' else [None,None,None])
        # shorthand / expression
        expr=self.parse_assign_expr()
        if self.at(':'):
            ct=self.advance(); val=self.parse_assign_expr()
            return self.node('pair',start.start,val.end,[expr,self.tnode(ct),val])
        if expr.kind=='identifier':
            expr.kind='shorthand_property_identifier' if self.lang in ('JavaScript','TypeScript','Tsx') else expr.kind
        return expr
    def parse_primary(self):
        t=self.peek()
        if t.type=='ident':
            txt=t.text
            if txt=='function':
                return self.parse_function(is_decl=False)
            if txt=='class':
                # class expression: reuse decl but kind?
                node=self.parse_class_decl(); 
                return node
            if txt in ('true','false'):
                tok=self.advance(); return leaf_node(txt,tok,self.src)
            if txt in ('null',):
                tok=self.advance(); return leaf_node('null',tok,self.src)
            if txt in ('None',):
                tok=self.advance(); return leaf_node('none',tok,self.src)
            if txt in ('this','super'):
                tok=self.advance(); return leaf_node(txt,tok,self.src)
            tok=self.advance(); return leaf_node('identifier',tok,self.src)
        if t.type=='number':
            tok=self.advance(); kind='number'
            if self.lang=='Python': kind='integer' if re.fullmatch(r'[0-9_]+',tok.text or '') or (tok.text and tok.text.lower().startswith(('0x','0o','0b'))) else 'float'
            if self.lang in ('C','Cpp','Go','Rust'): kind='int_literal' if self.lang=='Rust' else ('number_literal' if self.lang in ('C','Cpp') else 'int_literal')
            return leaf_node(kind,tok,self.src)
        if t.type=='string':
            tok=self.advance(); kind='string'
            if tok.text.startswith('`'): kind='template_string'
            if self.lang in ('C','Cpp'): kind='string_literal'
            if self.lang=='Rust': kind='string_literal'
            return leaf_node(kind,tok,self.src)
        if t.text=='(':
            # could be arrow params handled by caller assign check after returning paren
            return self.parse_paren_expr()
        if t.text=='[':
            return self.parse_array()
        if t.text=='{':
            return self.parse_object()
        if t.text=='<':
            # JSX / html like
            node=self.try_parse_jsx()
            if node: return node
            lt=self.advance(); return self.tnode(lt)
        if t.text in ('...','*','**'):
            rt=self.advance(); inner=self.parse_assign_expr(); return self.node('spread_element',rt.start,inner.end,[self.tnode(rt),inner])
        # keyword identifiers like string types etc as identifiers in some contexts
        # fallback token
        tok=self.advance(); 
        # if token is punctuation, make token node but to avoid infinite, mark error if unexpected ')',']','}',',',':',';'
        if tok.text in (')',']','}',',',':',';'):
            self.has_error=True
            # step back? The token consumed as leaf would affect matches; but parsing failures expected
            return Node(tok.text,tok.start,tok.end,[],[],False,self.src)
        return Node(tok.text,tok.start,tok.end,[],[],False,self.src)
    def try_parse_jsx(self):
        save_pos=self.pos; save_err=self.has_error
        lt=self.peek()
        # JSX: < identifier ... > children </...>  or <identifier ... />
        if self.peek(1).type!='ident' and self.peek(1).text not in ('>',):
            return None
        start=self.advance() # <
        children=[self.tnode(start)]
        # element name
        if self.peek().type=='ident':
            nt=self.advance(); children.append(leaf_node('identifier',nt,self.src))
            while self.at('.'):
                children.append(self.tnode(self.advance())); 
                if self.peek().type=='ident': children.append(leaf_node('identifier',self.advance(),self.src))
        attrs_start=len(children)
        # opening element node will be constructed later; parse attributes
        attr_nodes=[]
        while not self.at_eof() and not self.at('>') and not (self.at('/') ):
            if self.peek().type=='ident':
                nt=self.advance(); ach=[leaf_node('property_identifier',nt,self.src)]
                if self.at('='):
                    ach.append(self.tnode(self.advance()))
                    if self.peek().type=='string': ach.append(leaf_node('string',self.advance(),self.src))
                    elif self.at('{'):
                        ot=self.advance(); e=self.parse_expression(); ct=self.expect('}'); ach.append(self.node('jsx_expression',ot.start,ct.end,[self.tnode(ot),e,self.tnode(ct)]))
                    else: ach.append(self.parse_primary())
                attr_nodes.append(self.node('jsx_attribute',nt.start,ach[-1].end,ach)); continue
            if self.at('{'):
                ot=self.advance(); e=self.parse_expression(); ct=self.expect('}'); attr_nodes.append(self.node('jsx_expression',ot.start,ct.end,[self.tnode(ot),e,self.tnode(ct)])); continue
            break
        self_closing=False
        if self.at('/'):
            self.advance(); self_closing=True
        if not self.at('>'):
            self.pos=save_pos; self.has_error=save_err; return None
        gt=self.advance()
        opening_children=[self.tnode(lt)]+children[1:]+attr_nodes+[self.tnode(gt)]
        if self_closing:
            # include slash token? omitted
            return self.node('jsx_self_closing_element',lt.start,gt.end,opening_children)
        opening=self.node('jsx_opening_element',lt.start,gt.end,opening_children)
        elems=[opening]
        # children until </
        while not self.at_eof():
            if self.at('<') and self.peek(1).text=='/':
                clt=self.advance(); slash=self.advance(); cch=[self.tnode(clt),self.tnode(slash)]
                if self.peek().type=='ident': cch.append(leaf_node('identifier',self.advance(),self.src))
                cgt=self.expect('>'); cch.append(self.tnode(cgt))
                closing=self.node('jsx_closing_element',clt.start,cgt.end,cch); elems.append(closing); break
            if self.at('<'):
                child=self.try_parse_jsx()
                if child: elems.append(child); continue
                else: break
            if self.at('{'):
                ot=self.advance(); 
                if not self.at('}'): e=self.parse_expression()
                else: e=None
                ct=self.expect('}')
                if e: elems.append(self.node('jsx_expression',ot.start,ct.end,[self.tnode(ot),e,self.tnode(ct)]))
                continue
            # text: consume tokens until < or {
            txt_start=self.peek(); txt_end=txt_start
            consumed=False
            while not self.at_eof() and not self.at('<') and not self.at('{'):
                txt_end=self.advance(); consumed=True
            if consumed:
                elems.append(Node('jsx_text',txt_start.start,txt_end.end,[],[],True,self.src))
            else: break
        return self.node('jsx_element',lt.start,elems[-1].end,elems)
    # ---------- Python statements ----------
    def line_indent(self,line_idx):
        if 0<=line_idx<len(self.lines):
            s=self.lines[line_idx]; return len(s)-len(s.lstrip(' \t'))
        return 0
    def parse_py_statements(self,min_indent,end_keywords=()):
        children=[]
        while not self.at_eof():
            t=self.peek()
            # determine line indent of token
            line_idx=self.src.count('\n',0,t.start)
            indent=self.line_indent(line_idx)
            if indent < min_indent: break
            if t.text in end_keywords: break
            stmt=self.parse_py_statement(min_indent)
            if stmt: children.append(stmt)
            else: break
        return children
    def parse_py_block(self,header_start,min_indent_parent):
        # after colon, block: if next token on same line as header and not newline, parse single statement suite; else indented statements
        # Header line:
        # Find tokens after colon: parser position currently after colon token
        header_line=self.src.count('\n',0,header_start)
        # if next token is on same line, parse statement(s) on same line (separated by ;)
        children=[]
        if not self.at_eof() and self.src.count('\n',0,self.peek().start)==header_line:
            # same line suite
            while not self.at_eof():
                st=self.parse_py_statement(min_indent_parent,inline=True)
                if st: children.append(st)
                if self.at(';'): self.advance(); continue
                break
            start=children[0].start if children else header_start
            end=children[-1].end if children else header_start
            return self.node('block',start,end,children)
        # indented
        if self.at_eof(): return self.node('block',header_start,header_start,[])
        next_line=self.src.count('\n',0,self.peek().start)
        indent=self.line_indent(next_line)
        children=self.parse_py_statements(indent)
        start=children[0].start if children else header_start
        end=children[-1].end if children else header_start
        return self.node('block',start,end,children)
    def parse_py_statement(self,min_indent=0,inline=False):
        if self.at_eof(): return None
        t=self.peek(); txt=t.text
        # decorators
        if txt=='@':
            start=self.advance(); expr=self.parse_expression(); dec=self.node('decorator',start.start,expr.end,[self.tnode(start),expr])
            nxt=self.parse_py_statement(min_indent)
            if nxt:
                return self.node('decorated_definition',start.start,nxt.end,[dec,nxt])
            return dec
        if txt in ('def','async'):
            return self.parse_py_function()
        if txt=='class': return self.parse_py_class()
        if txt=='if': return self.parse_py_if(min_indent)
        if txt=='for': return self.parse_py_for(min_indent)
        if txt=='while': return self.parse_py_while(min_indent)
        if txt=='try': return self.parse_py_try(min_indent)
        if txt=='with':
            tok=self.advance(); children=[self.tnode(tok)]
            # with items until :
            items=[]
            while not self.at_eof() and not self.at(':'):
                if self.at(','): children.append(self.tnode(self.advance())); continue
                children.append(self.parse_expression())
            if self.at(':'): children.append(self.tnode(self.advance()))
            blk=self.parse_py_block(tok.start,min_indent); children.append(blk)
            return self.node('with_statement',tok.start,children[-1].end,children)
        if txt in ('return','yield'):
            tok=self.advance(); children=[self.tnode(tok)]
            # if next token on same line
            if not self.at_eof() and self.src.count('\n',0,self.peek().start)==self.src.count('\n',0,tok.start) and not self.at(';'):
                children.append(self.parse_expression())
                while self.at(','): 
                    # tuple return
                    children.append(self.tnode(self.advance()));
                    if self.src.count('\n',0,self.peek().start)==self.src.count('\n',0,tok.start): children.append(self.parse_expression())
            if self.at(';'): self.advance()
            return self.node('return_statement',tok.start,children[-1].end,children)
        if txt in ('import','from'): return self.parse_py_import()
        if txt in ('pass','break','continue'):
            tok=self.advance(); node=self.node(f'{txt}_statement',tok.start,tok.end,[self.tnode(tok)])
            if self.at(';'): self.advance()
            return node
        if txt in ('global','nonlocal','assert','del','raise','print'):
            tok=self.advance(); children=[self.tnode(tok)]
            line=self.src.count('\n',0,tok.start)
            while not self.at_eof() and self.src.count('\n',0,self.peek().start)==line and not self.at(';'):
                children.append(self.parse_expression())
                if self.at(','): children.append(self.tnode(self.advance())); continue
                break
            if self.at(';'): self.advance()
            kind={'global':'global_statement','nonlocal':'nonlocal_statement','assert':'assert_statement','del':'delete_statement','raise':'raise_statement','print':'print_statement'}.get(txt,'expression_statement')
            return self.node(kind,tok.start,children[-1].end,children)
        # generic expression / assignment statement: parse until end of line (?) parse_expression stops at tokens not operators; semicolon
        expr=self.parse_expression()
        # Python tuple: comma separated at statement level
        if self.at(','):
            children=[expr]
            while self.at(','):
                children.append(self.tnode(self.advance()))
                # if next on same line and not closing
                if not self.at_eof() and self.src.count('\n',0,self.peek().start)==self.src.count('\n',0,expr.start):
                    # might be trailing comma
                    if self.peek().text in ('\n',): break
                    children.append(self.parse_expression())
                else: break
            # if assignment after tuple? already parse_assign handles first? Tuple assignment: parse_assign would not include commas, so if next is = after tuple, handle
            if self.at('='):
                eq=self.advance(); rhs=self.parse_expression()
                tup=self.node('tuple',children[0].start,children[-1].end,children)
                return self.node('assignment',tup.start,rhs.end,[tup,self.tnode(eq),rhs])
            expr=self.node('tuple',children[0].start,children[-1].end,children)
        if self.at(';'): self.advance()
        # expression_statement wrapper for python
        return self.node('expression_statement',expr.start,expr.end,[expr])
    def parse_py_function(self):
        start=self.peek(); children=[]
        if self.at('async'): children.append(self.tnode(self.advance()))
        dtok=self.advance(); children.append(self.tnode(dtok)) # def
        if self.peek().type=='ident': children.append(leaf_node('identifier',self.advance(),self.src))
        params=self.parse_params(); children.append(params)  # python parameters kind via km override in parse_params? It uses km['parameters'] which is parameters for python good.
        if self.at('->'):
            children.append(self.tnode(self.advance())); children.append(self.parse_type())
        ct=self.expect(':'); children.append(self.tnode(ct))
        blk=self.parse_py_block(start.start,0); children.append(blk)
        return self.node('function_definition',start.start,children[-1].end,children)
    def parse_py_class(self):
        tok=self.advance(); children=[self.tnode(tok)]
        if self.peek().type=='ident': children.append(leaf_node('identifier',self.advance(),self.src))
        if self.at('('):
            # bases as parameters-like parenthesized
            children.append(self.parse_paren_expr())
        ct=self.expect(':'); children.append(self.tnode(ct))
        blk=self.parse_py_block(tok.start,0); children.append(blk)
        return self.node('class_definition',tok.start,children[-1].end,children)
    def parse_py_if(self,min_indent):
        tok=self.advance(); children=[self.tnode(tok)]
        children.append(self.parse_expression())
        ct=self.expect(':'); children.append(self.tnode(ct))
        blk=self.parse_py_block(tok.start,min_indent); children.append(blk)
        # elif / else at same indent
        while not self.at_eof():
            nt=self.peek()
            line=self.src.count('\n',0,nt.start); ind=self.line_indent(line)
            if ind!=min_indent and ind>min_indent: break
            # min_indent is indent of if line; parse_py_statements passes? Actually caller passes min_indent which for top is 0, nested block indent is token's line indent not parameter. Use current if token indent
            # Determine if token line indent equals if line indent
            if_line=self.src.count('\n',0,tok.start); if_ind=self.line_indent(if_line)
            if ind!=if_ind: break
            if nt.text=='elif':
                etok=self.advance(); echildren=[self.tnode(etok),self.parse_expression()]
                c=self.expect(':'); echildren.append(self.tnode(c)); echildren.append(self.parse_py_block(etok.start,min_indent))
                children.append(self.node('elif_clause',etok.start,echildren[-1].end,echildren)); continue
            if nt.text=='else':
                etok=self.advance(); echildren=[self.tnode(etok)]; c=self.expect(':'); echildren.append(self.tnode(c)); echildren.append(self.parse_py_block(etok.start,min_indent))
                children.append(self.node('else_clause',etok.start,echildren[-1].end,echildren)); break
            break
        return self.node('if_statement',tok.start,children[-1].end,children)
    def parse_py_for(self,min_indent):
        tok=self.advance(); children=[self.tnode(tok)]
        # variables until 'in'
        children.append(self.parse_expression())  # may stop at in? parse_binary handles in as binary so it'll consume... Need custom: parse target until in token at top.
        # Our parse_expression above will have parsed "x in y" as binary_operator with in. That's wrong for for.
        # Patch: if children last is binary with in, reconstruct?
        # Simplify: accept binary structure; original for_statement children: var, in, iter, :, block. Parser matching with pattern parsed same way will be consistent.
        if self.at(':'):
            children.append(self.tnode(self.advance()))
        else:
            # if binary didn't include colon handling
            if not self.at(':'):
                # maybe expression stopped before in
                if self.at('in'):
                    children.append(self.tnode(self.advance())); children.append(self.parse_expression())
                ct=self.expect(':'); children.append(self.tnode(ct))
            else: children.append(self.tnode(self.advance()))
