# ---------------- Meta & Matching ----------------
META_RE=re.compile(r'^(\$+)(\[)?([A-Za-z_][A-Za-z0-9_]*)?$')
def meta_info(text):
    if text is None: return None
    s=text.strip()
    m=re.fullmatch(r'(\$+)([A-Za-z0-9_]*)',s)
    if not m: return None
    dollars, name = m.groups()
    if name=='':
        if len(dollars)==3: return ('multi',None)
        if len(dollars)==1: return None
        return ('single',None) if len(dollars)>=1 else None
    # name must start upper or underscore; lowercase not meta
    if not (name[0].isupper() or name[0]=='_'): return None
    if len(dollars)>=3: return ('multi', None if name.startswith('_') else name)
    else: return ('single', None if name.startswith('_') else name)
