                if i+1<len(line) and line[i+1]=="'": i+=2; continue
                in_s=False
        elif in_d:
            if c=='\\': i+=2; continue
            if c=='"': in_d=False
        else:
            if c=="'": in_s=True
            elif c=='"': in_d=True
            elif c=='#' and (i==0 or line[i-1] in ' \t'):
                return line[:i].rstrip()
        i+=1
    return line.rstrip()

def _parse_yaml_scalar(s):
    s=s.strip()
    if s=='' : return None
    if s.startswith('"') and s.endswith('"') and len(s)>=2:
        try: return json.loads(s)
        except:
            try: return bytes(s[1:-1],'utf-8').decode('unicode_escape')
            except: return s[1:-1]
    if s.startswith("'") and s.endswith("'") and len(s)>=2:
        return s[1:-1].replace("''","'")
    if s.startswith('{') or s.startswith('['):
        val,_=_parse_flow(s,0)
        return val
    low=s.lower()
    if low in ('true','yes','on'): return True
    if low in ('false','no','off'): 
        # Careful: severity value 'off' is plain scalar in yaml, PyYAML would parse off as False (YAML 1.1). Serde_yaml (YAML)?? Original uses serde_yaml which is YAML 1.2? It treats 'off' as string? Severity off worked when written severity: off - if YAML parser turned it false, serde would fail. So serde likely parses off as string 'off' (1.2 core only true/false). Therefore do NOT convert yes/no/on/off.
        pass
    if low in ('false',): return False
    if low=='true': return True
    if low in ('null','~'): return None
    # re-evaluate only true/false/null per YAML1.2
    if s=='true' or s=='True' or s=='TRUE': return True
    if s=='false' or s=='False' or s=='FALSE': return False
    try:
        if re.fullmatch(r'[-+]?\d+',s): return int(s)
        if re.fullmatch(r'[-+]?(\d+\.\d*|\.\d+|\d+)([eE][-+]?\d+)?',s): return float(s)
    except: pass
