def _parse_flow(s,i):
    # skip ws
    while i<len(s) and s[i] in ' \t': i+=1
    if i>=len(s): return None,i
    if s[i]=='{':
        d={}; i+=1
        while True:
            while i<len(s) and s[i] in ' \t': i+=1
            if i<len(s) and s[i]=='}': return d,i+1
            # key
            if s[i] in ('"',"'"):
