    if not isinstance(rule,dict): return False
    if 'pattern' in rule or 'kind' in rule or 'matches' in rule: return True
    if isinstance(rule.get('all'),list) and rule['all'] and any(has_positive(x) for x in rule['all']): return True
    if isinstance(rule.get('any'),list) and rule['any'] and any(has_positive(x) for x in rule['any']): return True
    return False

class CompiledPattern:
    def __init__(self,text,lang,strictness='smart',selector=None,context_text=None):
        self.text=text; self.lang=lang; self.strictness=strictness or 'smart'; self.selector=selector
        src_for_parse=context_text if context_text is not None else text
        self.src_for_parse=src_for_parse
        root,parser=parse_source(src_for_parse,lang)
        self.root=root; self.parser=parser
        node,err=extract_pattern_root(root,parser,selector=selector,lang=lang)
        self.pattern_node=node; self.error=err; self.has_parser_error=parser.has_error
    def is_valid(self):
        return self.pattern_node is not None and not self.error

_pattern_cache={}
def get_pattern(text,lang,strictness='smart',selector=None,context=None):
    key=(text,lang,strictness,selector,context)
    if key not in _pattern_cache:
        _pattern_cache[key]=CompiledPattern(text,lang,strictness,selector,context)
    return _pattern_cache[key]

class RuleMatcher:
    def __init__(self,config,lang,utils=None,global_utils=None,source_name='INLINE_RULES'):
        self.config=config; self.lang=lang; self.source_name=source_name
        self.utils={}
        if global_utils: self.utils.update(global_utils)
        if isinstance(config.get('utils'),dict): self.utils.update(config['utils'])
        if utils: self.utils.update(utils)
        # local utils from config.utils already
        self.rule=config.get('rule')
        self.constraints=config.get('constraints') or {}
        # validate later in compile()
    def validate_rule(self,rule,top=False):
        if not isinstance(rule,dict):
            raise RuleError('rule-not-dict',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule must have one positive matcher."])
        unknown=[k for k in rule.keys() if k not in RULE_KEYS]
        if unknown:
            exp="`, `".join(['pattern','kind','regex','nthChild','range','inside','has','precedes','follows','all','any','not','matches'])
            # serde message format uses backticks
            msg=f"unknown field `{unknown[0]}`, expected one of `pattern`, `kind`, `regex`, `nthChild`, `range`, `inside`, `has`, `precedes`, `follows`, `all`, `any`, `not`, `matches`"
            raise RuleError('unknown-field',["Fail to parse yaml as RuleConfig",msg])
        if not rule:
            raise RuleError('empty',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule must have one positive matcher."])
        if not has_positive(rule):
            raise RuleError('no-kinds',["Rule must specify a set of AST kinds to match. Try adding `kind` rule."])
        # validate subparts
        if 'pattern' in rule:
            p=rule['pattern']
            if not isinstance(p,(str,dict)):
                raise RuleError('bad-pattern-type',["Fail to parse yaml as RuleConfig","data did not match any variant of untagged enum PatternStyle"])
            if isinstance(p,dict):
                if 'context' not in p:
                    raise RuleError('bad-pattern-type',["Fail to parse yaml as RuleConfig","data did not match any variant of untagged enum PatternStyle"])
                ctx=p.get('context'); sel=p.get('selector'); strict=p.get('strictness')
                if not isinstance(ctx,str):
                    raise RuleError('bad-pattern-type',["Fail to parse yaml as RuleConfig","data did not match any variant of untagged enum PatternStyle"])
                if sel and self.lang in KIND_SETS and KIND_SETS[self.lang] and sel not in KIND_SETS[self.lang]:
                    raise RuleError('invalid-kind',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid pattern matcher.",f"Kind `{sel}` is invalid."])
                cp=get_pattern(ctx,self.lang,strict or 'smart',sel,None)
                if cp.error:
                    raise RuleError('pattern-err',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid pattern matcher.",cp.error])
                if cp.has_parser_error and not cp.error:
                    raise RuleError('no-kinds',["Rule must specify a set of AST kinds to match. Try adding `kind` rule."])
            else:
                cp=get_pattern(p,self.lang,'smart',None,None)
                if cp.error:
                    raise RuleError('pattern-err',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid pattern matcher.",cp.error])
                if cp.has_parser_error:
                    raise RuleError('no-kinds',["Rule must specify a set of AST kinds to match. Try adding `kind` rule."])
        if 'kind' in rule:
            k=rule['kind']
            if self.lang in KIND_SETS and KIND_SETS[self.lang] and isinstance(k,str) and k not in KIND_SETS[self.lang]:
                # Original would error? When kind invalid, likely: similar pattern message
                raise RuleError('invalid-kind',["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid kind matcher.",f"Kind `{k}` is invalid."])
        for key in ('all','any'):
            if key in rule:
                if isinstance(rule[key],list):
                    for sub in rule[key]: self.validate_rule(sub)
        for key in ('inside','has','precedes','follows','not'):
            if key in rule and isinstance(rule[key],dict):
                # relational subrules may omit positive? They normally have pattern/kind. If they only have stopBy etc, skip validation of positive? We'll validate non-relational parts by stripping stopBy/field
                sub={kk:vv for kk,vv in rule[key].items() if kk not in ('stopBy','field')}
                if sub: 
                    # subrule validation should not require? but try; if it fails no-positive, propagate as no-kinds? Original for inside:{regex:...} maybe requires kind
                    self.validate_rule(sub)
        if 'matches' in rule:
            m=rule['matches']
            # string names must exist in utils?
            names=[]
            if isinstance(m,str): names=[m]
            elif isinstance(m,dict): names=list(m.keys())
            elif isinstance(m,list):
                for item in m:
                    if isinstance(item,str): names.append(item)
                    elif isinstance(item,dict): names.extend(item.keys())
            for nm in names:
                if nm not in self.utils:
                    # error message unknown - approximate
                    raise RuleError('util-not-found',["Fail to parse yaml as Rule.","`rule` is not configured correctly.",f"Utility `{nm}` is not defined."])
    def validate(self):
        if not isinstance(self.config,dict):
            raise RuleError('bad-config',["Fail to parse yaml as RuleConfig","data did not match any variant"])
        if 'language' not in self.config or self.config.get('language') is None:
            raise RuleError('missing-language',["Fail to parse yaml as RuleConfig","missing field `language`"])
        if 'rule' not in self.config or self.config.get('rule') is None:
            raise RuleError('missing-rule',["Fail to parse yaml as RuleConfig","missing field `rule`"])
        if 'severity' in self.config and self.config['severity'] not in ('hint','info','warning','error','off'):
            # message includes location in yaml unknown
            raise RuleError('bad-severity',["Fail to parse yaml as RuleConfig",f"severity: unknown variant `{self.config['severity']}`, expected one of `hint`, `info`, `warning`, `error`, `off`"])
        # language validity checked earlier
        self.validate_rule(self.rule,top=True)
        # labels check
        if isinstance(self.config.get('labels'),dict):
            defined=collect_meta_names(self.rule)
            if isinstance(self.constraints,dict):
                for cr in self.constraints.values(): defined|=collect_meta_names(cr)
            # also transform names? no
            for lab_name in self.config['labels'].keys():
                if lab_name not in defined:
                    raise RuleError('label-undefined',[f"Label meta-variable `{lab_name}` must be defined in `rule` or `constraints`."])
        # transform undefined check
        if isinstance(self.config.get('transform'),dict):
            defined=collect_meta_names(self.rule)
            if isinstance(self.constraints,dict):
                for cr in self.constraints.values(): defined|=collect_meta_names(cr)
            for out_name,trans in self.config['transform'].items():
                src_name=None
                if isinstance(trans,dict):
                    # find inner dict values
                    for tk,tv in trans.items():
                        if isinstance(tv,dict) and 'source' in tv: src_name=tv['source']
                        elif tk=='source': src_name=trans.get('source')
                    # also string form
                elif isinstance(trans,str):
                    src_name=trans
                if isinstance(src_name,str):
                    mm=re.search(r'\$+([A-Z][A-Za-z0-9_]*)',src_name)
                    if mm and mm.group(1) not in defined and mm.group(1) not in self.config['transform']:
                        raise RuleError('transform-undefined',["Fail to parse yaml as Rule.",f"Undefined meta var `{mm.group(1)}` used in `transform`."])
                # rewrite rewriters ids check maybe
        # constraints validate
        if isinstance(self.constraints,dict):
            for var,cr in self.constraints.items():
                if isinstance(cr,dict): self.validate_rule(cr)
    # evaluation
    def eval_rule(self,rule,candidate,env):
        if not isinstance(rule,dict): return False
        local_env=env.copy()
        # order: pattern, kind, regex, nthChild, range, all, any, not, matches, relational
        if 'pattern' in rule:
            ok=self.eval_pattern(rule['pattern'],candidate,local_env)
            if not ok: return False
        if 'kind' in rule:
            if candidate.kind!=rule['kind']: return False
        if 'regex' in rule:
            try:
                if not re.search(str(rule['regex']),candidate.text): return False
            except re.error:
                return False
        if 'nthChild' in rule:
            if not self.eval_nth(candidate,rule['nthChild'],local_env): return False
        if 'range' in rule:
            if not self.eval_range(candidate,rule['range']): return False
        if 'all' in rule and isinstance(rule['all'],list):
            for sub in rule['all']:
                if not self.eval_rule(sub,candidate,local_env): return False
        if 'any' in rule and isinstance(rule['any'],list):
            any_ok=False
            for sub in rule['any']:
                trial=local_env.copy()
                if self.eval_rule(sub,candidate,trial): local_env.absorb(trial); any_ok=True; break
            if not any_ok: return False
        if 'not' in rule:
            trial=Env()
            if self.eval_rule(rule['not'],candidate,trial): return False
        if 'matches' in rule:
            if not self.eval_matches(rule['matches'],candidate,local_env): return False
        for rel_key in ('inside','has','precedes','follows'):
            if rel_key in rule:
                if not self.eval_relation(rel_key,rule[rel_key],candidate,local_env): return False
        env.absorb(local_env); return True
    def eval_pattern(self,pat,candidate,env):
        if isinstance(pat,str):
            cp=get_pattern(pat,self.lang,'smart',None,None)
            if not cp.pattern_node: return False
            return match_node(cp.pattern_node,candidate,env,cp.strictness)
        elif isinstance(pat,dict):
            ctx=pat.get('context'); sel=pat.get('selector'); strict=pat.get('strictness') or 'smart'
            cp=get_pattern(ctx,self.lang,strict,sel,None)
            if not cp.pattern_node: return False
            return match_node(cp.pattern_node,candidate,env,strict)
        return False
    def eval_nth(self,candidate,nth,env):
        parent=candidate.parent
        if parent is None: return False
        siblings=[c for c in parent.children if c.named]
        if candidate not in siblings: return False
        pos_def=nth; of_rule=None; reverse=False
        if isinstance(nth,dict):
            pos_def=nth.get('position'); of_rule=nth.get('ofRule'); reverse=bool(nth.get('reverse'))
        candidates=siblings
        if of_rule is not None:
            filtered=[]
            for sib in candidates:
                trial=Env()
                if self.eval_rule(of_rule,sib,trial): filtered.append(sib)
            candidates=filtered
            if candidate not in candidates: return False
        idx=candidates.index(candidate)
        if reverse: idx=len(candidates)-1-idx
        position_1=idx+1
        # int -> 1-based? Original nthChild:1 matches first.
        if isinstance(pos_def,int):
            return position_1==pos_def or idx==pos_def and False  # explicit 1-based
            # but what about 0? If user uses 0, 1-based will fail for first; original maybe 0-based? earlier test 1 matched first, so 1-based.
        s=str(pos_def).strip().lower()
        if s=='odd': return position_1%2==1
        if s=='even': return position_1%2==0
        m=re.fullmatch(r'([+-]?\d*)n(?:([+-])(\d+))?',s.replace(' ',''))
        if m:
            a_str=m.group(1); b=0
            if m.group(2): b=int(m.group(3))*(1 if m.group(2)=='+' else -1)
            if a_str in ('','+'): a=1
            elif a_str=='-': a=-1
            else: a=int(a_str)
            # position = a*n + b for n>=0
            if a==0: return position_1==b
            diff=position_1-b
            return diff%a==0 and diff//a>=0
        try:
            return position_1==int(s)
        except: return False
    def eval_range(self,candidate,rng):
        if not isinstance(rng,dict): return False
        try:
            src=candidate.src; starts=line_starts(src)
            sl,sc=pos_to_linecol(src,starts,candidate.start); el,ec=pos_to_linecol(src,starts,candidate.end)
            return sl==rng['start']['line'] and sc==rng['start']['column'] and el==rng['end']['line'] and ec==rng['end']['column']
        except: return False
    def eval_matches(self,matches,candidate,env):
        utilities=[]
        if isinstance(matches,str): utilities=[(matches,None)]
        elif isinstance(matches,dict):
            for k,v in matches.items(): utilities.append((k,v))
        elif isinstance(matches,list):
            for item in matches:
                if isinstance(item,str): utilities.append((item,None))
                elif isinstance(item,dict):
                    for k,v in item.items(): utilities.append((k,v))
        else: return False
        for name,params in utilities:
            util_rule=self.utils.get(name)
            if util_rule is None: return False
            trial=env.copy()
            if not self.eval_rule(util_rule,candidate,trial): return False
            # params: dict var->rule ; check captured node for that var against subrule
            if isinstance(params,dict):
                for var,subrule in params.items():
                    node=trial.single.get(var)
                    if node is None: return False
                    sub_trial=Env()
                    if not self.eval_rule(subrule,node,sub_trial): return False
                    # merge subcaptures?
                    for kk,vv in sub_trial.single.items():
                        if kk not in trial.single: trial.single[kk]=vv
            env.absorb(trial)
        return True
    def eval_relation(self,rel_key,relation,candidate,env):
        if not isinstance(relation,dict): return False
        stop_by=relation.get('stopBy','neighbor')
        field=relation.get('field')
        subrule={k:v for k,v in relation.items() if k not in ('stopBy','field')}
        if not subrule: return False
        related_candidates=[]
        if rel_key=='inside':
            ancestors=[]
            p=candidate.parent
            while p is not None: ancestors.append(p); p=p.parent
            if stop_by=='neighbor': related_candidates=ancestors[:1]
            elif stop_by=='end': related_candidates=ancestors
            elif isinstance(stop_by,dict):
                for anc in ancestors:
                    trial=Env()
                    if self.eval_rule(stop_by,anc,trial): break
                    related_candidates.append(anc)
            else: related_candidates=ancestors
            if field:
                # filter ancestors such that candidate path child field == field (for neighbor this is candidate field in parent; for anc, first child on path)
                filtered=[]
                for anc in related_candidates:
                    # find child of anc that is ancestor of candidate (or candidate)
                    node=candidate
                    while node.parent is not None and node.parent is not anc: node=node.parent
                    if node.parent is anc:
                        idx=anc.children.index(node); 
                        if idx < len(anc.fields) and anc.fields[idx]==field: filtered.append(anc)
                related_candidates=filtered
        elif rel_key=='has':
            if stop_by=='neighbor': related_candidates=[c for c in candidate.children if c.named]
            elif stop_by=='end':
                related_candidates=[n for n in walk(candidate,True) if n is not candidate and n.named]
            elif isinstance(stop_by,dict):
                cand=[]
                for n in walk(candidate,True):
                    if n is candidate: continue
                    if not n.named: continue
                    # prune if ancestor (between) matches stopby? approx: if n itself matches stopby skip? Original stopBy rule stops searching beyond node matching.
                    cand.append(n)
                related_candidates=cand
            if field:
                related_candidates=[c for c in related_candidates if c in candidate.children and candidate.fields[candidate.children.index(c)]==field]
        elif rel_key in ('precedes','follows'):
            parent=candidate.parent
            if parent is None: return False
            siblings=[c for c in parent.children if c.named]
            if candidate not in siblings: return False
            idx=siblings.index(candidate)
            if rel_key=='precedes':
                seq=siblings[idx+1:]
            else:
                seq=list(reversed(siblings[:idx]))
            if stop_by=='neighbor': related_candidates=seq[:1]
            else: related_candidates=seq
        # try in order
        for related in related_candidates:
            trial=env.copy()
            if self.eval_rule(subrule,related,trial):
                # merged captures, add secondary
                trial.secondary.append(related)
                env.absorb(trial); return True
            # if stopBy is a dict rule and related matches it, stop searching further for has (?) - ancestors already handled
            if isinstance(stop_by,dict):
                t2=Env()
                if self.eval_rule(stop_by,related,t2):
                    # For descendants, do not search deeper than this node - our walk linear can't prune easily; break if related is container? Approx continue (might overmatch)
                    pass
        return False
    def match(self,candidate):
        env=Env()
        if not self.eval_rule(self.rule,candidate,env): return None
        # constraints
        if isinstance(self.constraints,dict):
            for var,cr in self.constraints.items():
                node=env.single.get(var)
                if node is None:
                    # if constraint var is multi?
                    if var in env.multi and env.multi[var]: node=env.multi[var][0]
                    else: return None
                trial=Env()
                if not self.eval_rule(cr,node,trial): return None
                # merge trial captures that are new
                for k,v in trial.single.items():
                    if k not in env.single: env.single[k]=v
                for k,v in trial.multi.items():
                    if k not in env.multi: env.multi[k]=v
        return env

def compute_transformed(config,env,rule_matcher=None,src_code=None):
    transformed={}
    trans_cfg=config.get('transform') if isinstance(config,dict) else None
    if not isinstance(trans_cfg,dict): return transformed
    for out_name,trans in trans_cfg.items():
        val=""
        if isinstance(trans,str):
            # could be $VAR
            val=render_template(trans,env,transformed)
        elif isinstance(trans,dict):
            # single key form
            if 'substring' in trans and isinstance(trans['substring'],dict):
                sub=trans['substring']; source=sub.get('source','')
                src_text=var_source_text(source,env,transformed)
                start=sub.get('startChar'); end=sub.get('endChar')
                n=len(src_text)
                s_idx=0 if start is None else (start if start>=0 else n+start)
                e_idx=n if end is None else (end if end>=0 else n+end)
                s_idx=max(0,min(n,s_idx)); e_idx=max(0,min(n,e_idx))
                val=src_text[s_idx:e_idx] if e_idx>=s_idx else ""
            elif 'replace' in trans and isinstance(trans['replace'],dict):
                rep=trans['replace']; src_text=var_source_text(rep.get('source',''),env,transformed)
                pattern=rep.get('replace',''); by=rep.get('by','')
                try:
                    # convert Rust $1 style to python \g<1>
                    py_by=re.sub(r'\$(\d+)',r'\\g<\1>',str(by))
                    py_by=re.sub(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}',r'\\g<\1>',py_by)
                    val=re.sub(str(pattern),py_by,src_text)
                except Exception:
                    val=src_text
            elif 'convert' in trans and isinstance(trans['convert'],dict):
                conv=trans['convert']; src_text=var_source_text(conv.get('source',''),env,transformed)
                tocase=conv.get('toCase')
                # separatedBy handling: if present, split using those separators first
                seps=conv.get('separatedBy')
                words=None
                if isinstance(seps,list) and seps:
                    # Build split: separators are enums
                    s=src_text
                    # caseChange implies case splitting later in split_words
                    pattern_parts=[]
                    if 'dash' in seps: pattern_parts.append('-')
                    if 'underscore' in seps: pattern_parts.append('_')
                    if 'dot' in seps: pattern_parts.append(r'\.')
                    if 'slash' in seps: pattern_parts.append('/')
                    if 'space' in seps: pattern_parts.append(r'\s')
                    if pattern_parts:
                        parts=re.split('['+' '.join(pattern_parts)+']' if False else '|'.join(pattern_parts),s)
                        # then case split each
                        words=[]
                        for part in parts:
                            if 'caseChange' in seps: words.extend(split_words_case(part))
                            else: words.append(part)
                    else:
                        words=split_words_case(s)
                else:
                    words=split_words_case(src_text)
                if tocase=='lowerCase': val=src_text.lower()
                elif tocase=='upperCase': val=src_text.upper()
                elif tocase=='capitalize': val=src_text[:1].upper()+src_text[1:] if src_text else ""
                elif tocase=='camelCase':
                    if words: val=words[0].lower()+''.join(w[:1].upper()+w[1:] for w in words[1:])
                    else: val=""
                elif tocase=='pascalCase':
                    val=''.join(w[:1].upper()+w[1:] for w in words) if words else ""
                elif tocase=='snakeCase':
                    val='_'.join(w.lower() for w in words) if words else ""
                elif tocase=='kebabCase':
                    val='-'.join(w.lower() for w in words) if words else ""
                else: val=src_text
            elif 'rewrite' in trans and isinstance(trans['rewrite'],dict):
                rw=trans['rewrite']; source=rw.get('source',''); rewriter_ids=rw.get('rewriters',[]); join_by=rw.get('joinBy') or ''
                val=apply_rewrite_transform(source,rewriter_ids,join_by,env,transformed,config,rule_matcher)
            else:
                # direct {source: ...} form ?
                val=""
        transformed[out_name]=val
    return transformed

def var_source_text(source,env,transformed):
    if not isinstance(source,str): return ""
    m=re.fullmatch(r'\$+([A-Za-z_][A-Za-z0-9_]*)',source.strip())
    if m:
        name=m.group(1)
        if source.strip().startswith('$$$'):
            return var_text_from_env(name,env,transformed) if name in env.multi else ""
        if name in env.single: return env.single[name].text
        if name in transformed: return transformed[name]
        if name in env.multi: return var_text_from_env(name,env,transformed)
        return ""
    # could be transformed name without $ ?
    if source in transformed: return transformed[source]
    return render_template(source,env,transformed)

def apply_rewrite_transform(source,rewriter_ids,join_by,env,transformed,config,rule_matcher):
    rewriters={}
    if isinstance(config.get('rewriters'),list):
        for rw in config['rewriters']:
            if isinstance(rw,dict) and 'id' in rw: rewriters[rw['id']]=rw
    # source nodes
    nodes=[]
    if isinstance(source,str):
        m=re.fullmatch(r'(\$+)([A-Za-z_][A-Za-z0-9_]*)',source.strip())
        if m:
            dollars,name=m.groups()
            if len(dollars)>=3: nodes=env.multi.get(name,[])
            else: 
                if name in env.single: nodes=[env.single[name]]
                elif name in env.multi: nodes=env.multi[name]
    results=[]
    for node in nodes:
        text=node.text
        # For each rewriter in order, attempt to rewrite inside node text: parse node's text as code? Use its source root matching within node subtree
        # Simpler: search matching nodes in original tree rooted at node (including node)
        new_text=text
        offset_shift=0
        # We need apply rewriters to submatches: collect matches for all rewriters in node subtree
        # Use node's src root? Find root by climbing parent
        # But operating on text string with replacements internal relative positions:
        replacements=[]
        # For each rewriter id, construct transient RuleMatcher (?) config
        for rid in rewriter_ids:
            rw=rewriters.get(rid)
            if not rw: continue
            rw_config={'id':rw.get('id',''),'language':config.get('language'),'rule':rw.get('rule'), 'fix':rw.get('fix'), 'utils':rw.get('utils') or config.get('utils')}
            # language for matcher from main config
            try:
                matcher=RuleMatcher(rw_config, rule_matcher.lang if rule_matcher else 'JavaScript', utils=config.get('utils'))
                # do not validate strictly (?)
            except: continue
            # walk subtree
            for cand in walk(node,True):
                if not cand.named: continue
                menv=matcher.match(cand)
                if menv is not None:
                    # render fix
                    fix_obj=rw.get('fix')
                    template=None
                    if isinstance(fix_obj,str): template=fix_obj
                    elif isinstance(fix_obj,dict): template=fix_obj.get('template')
                    elif isinstance(fix_obj,list) and fix_obj and isinstance(fix_obj[0],dict): template=fix_obj[0].get('template')
