            except: pass
            line=sys.stdin.buffer.readline()
        try: content_length=int(headers.get('content-length','0'))
        except: content_length=0
        if content_length<=0: continue
        body=sys.stdin.buffer.read(content_length)
        try: msg=json.loads(body.decode('utf-8'))
        except:
            lsp_send({"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":None}); continue
        method=msg.get('method'); mid=msg.get('id'); params=msg.get('params') or {}
        if method=='initialize':
