            lsp_send({"jsonrpc":"2.0","result":result,"id":mid}); initialized=True; continue
        if method=='initialized': continue
        if not initialized:
            if mid is not None: lsp_send({"jsonrpc":"2.0","error":{"code":-32002,"message":"Server not initialized"},"id":mid})
            continue
        if method=='shutdown':
            lsp_send({"jsonrpc":"2.0","result":None,"id":mid}); continue
        if method=='exit': break
        if method and method.startswith('textDocument/did'):
            td=params.get('textDocument',{})
            uri=td.get('uri')
            if method=='textDocument/didOpen':
                text=td.get('text',''); documents[uri]=text
                publish_diagnostics(uri,text,rules)
            elif method=='textDocument/didChange':
                changes=params.get('contentChanges') or []
                if changes: documents[uri]=changes[-1].get('text',documents.get(uri,''))
                publish_diagnostics(uri,documents.get(uri,''),rules)
            elif method=='textDocument/didClose':
                documents.pop(uri,None); lsp_send({"jsonrpc":"2.0","method":"textDocument/publishDiagnostics","params":{"uri":uri,"diagnostics":[]}})
            elif method=='textDocument/didSave':
                if uri in documents: publish_diagnostics(uri,documents[uri],rules)
            continue
        if method=='textDocument/hover':
