            # find rule match at position
            hover_text=None
            diag=find_hover(text,uri,rules,pos)
            if diag: lsp_send({"jsonrpc":"2.0","result":{"contents":{"kind":"markdown","value":diag}},"id":mid})
            else: lsp_send({"jsonrpc":"2.0","result":None,"id":mid})
            continue
        if method=='textDocument/codeAction':
            uri=params.get('textDocument',{}).get('uri'); text=documents.get(uri,'')
            actions=code_actions(uri,text,rules,params)
            lsp_send({"jsonrpc":"2.0","result":actions,"id":mid}); continue
        if method=='workspace/executeCommand':
            # applyAllFixes: params arguments [uri]
            args=params.get('arguments') or []
            if params.get('command')=='ast-grep.applyAllFixes' and args:
                uri=args[0] if isinstance(args[0],str) else (args[0].get('uri') if isinstance(args[0],dict) else None)
                # compute fix edits and send workspace/applyEdit request? Tower server might handle internally and reply null. Approx reply null.
            lsp_send({"jsonrpc":"2.0","result":None,"id":mid}); continue
        if mid is not None:
            lsp_send({"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found"},"id":mid})
    return 0
