p=pathlib.Path("main.py"); s=p.read_text()
# Replace parse_bash_statement and parse_bash_statements implementations (find segment from def parse_bash_statements to def _token_line)
start=s.index("    def parse_bash_statements(self):")
end=s.index("    def bash_word_node(self,toks):")
new='''    def parse_bash_statements(self,stop_words=None):
        stop_words=stop_words or set()
        children=[]
        while not self.at_eof() and self.peek().text not in stop_words:
            if self.at(';'):
                self.advance(); continue
            _b=self.pos; stmt=self.parse_bash_statement()
            if self.pos==_b: self.advance()
            if stmt: children.append(stmt)
        return children
    def _token_line(self,tok):
        return self.src.count('\\n',0,tok.start)
    def parse_bash_statement(self):
        t=self.peek()
        if t.text in ('if','while','until','for','case'):
            return self.parse_bash_compound()
        if t.text=='function':
            return self.parse_statement()
        line=self._token_line(t); toks_line=[]
        while not self.at_eof() and self._token_line(self.peek())==line and not self.at(';') and self.peek().text not in ('then','do','fi','done','else','elif','esac'):
            toks_line.append(self.advance())
        if self.at(';'): self.advance()
        if not toks_line: return None
        if toks_line[0].text in ('[','[['):
            # test command
            children=[]
            for tk in toks_line:
                if tk.text in ('[',']'): children.append(self.tnode(tk))
                elif tk.type=='ident': children.append(Node('word',tk.start,tk.end,[],[],True,self.src))
                else: children.append(self.tnode(tk))
            return self.node('test_command',toks_line[0].start,toks_line[-1].end,children)
        return self.bash_node_from_tokens(toks_line)
    def parse_bash_compound(self):
        t=self.peek(); kw=t.text
        if kw=='if':
            tok=self.advance(); children=[self.tnode(tok)]
            cond=self.parse_bash_statements({'then'}); children.extend(cond)
            if self.at('then'): children.append(self.tnode(self.advance()))
            body=self.parse_bash_statements({'elif','else','fi'}); children.extend(body)
            while self.at('elif'):
                et=self.advance(); ech=[self.tnode(et)]; ech.extend(self.parse_bash_statements({'then'}))
                if self.at('then'): ech.append(self.tnode(self.advance()))
                ech.extend(self.parse_bash_statements({'elif','else','fi'})); children.append(self.node('elif_clause',et.start,ech[-1].end,ech))
            if self.at('else'):
                et=self.advance(); ech=[self.tnode(et)]; ech.extend(self.parse_bash_statements({'fi'})); children.append(self.node('else_clause',et.start,ech[-1].end,ech))
            if self.at('fi'): children.append(self.tnode(self.advance()))
            return self.node('if_statement',tok.start,children[-1].end,children)
        if kw in ('while','until'):
            tok=self.advance(); children=[self.tnode(tok)]; children.extend(self.parse_bash_statements({'do'}))
            if self.at('do'): children.append(self.tnode(self.advance()))
            children.extend(self.parse_bash_statements({'done'}))
            if self.at('done'): children.append(self.tnode(self.advance()))
            return self.node('while_statement',tok.start,children[-1].end,children)
        if kw=='for':
            tok=self.advance(); children=[self.tnode(tok)]
            while not self.at_eof() and not self.at('do'):
                if self.at(';'): self.advance(); break
                tk=self.advance(); children.append(Node('word',tk.start,tk.end,[],[],True,self.src) if tk.type=='ident' else self.tnode(tk))
            if self.at('do'): children.append(self.tnode(self.advance()))
            children.extend(self.parse_bash_statements({'done'}))
            if self.at('done'): children.append(self.tnode(self.advance()))
            return self.node('for_statement',tok.start,children[-1].end,children)
        # fallback
        return self.parse_statement()
'''
s=s[:start]+new+s[end:]
pathlib.Path("main.py").write_text(s)
print("ok")
